void
process_bgp_update(netdissect_options *ndo, const u_char *dat, int length)
{
    const u_char *ep = dat + length;
    u_int total_length;
    u_int wrlen, attrlen;
    const u_char *cp;

    ND_PRINT((ndo, "BGP Update"));

    if (length < BGP_HDR_LEN) {
        ND_PRINT((ndo, "\n\t|%s", "truncated BGP header"));
        return;
    }

    ND_TCHECK2(*dat, BGP_HDR_LEN);
    ND_PRINT((ndo, "\n\tLength: %d", length));

    cp = dat + BGP_HDR_LEN;

    if (cp + 2 > ep) {
        ND_PRINT((ndo, "\n\t|%s", "truncated"));
        return;
    }

    wrlen = GET_BE_U_2(cp);
    cp += 2;

    if (wrlen > 0) {
        ND_PRINT((ndo, "\n\tWithdrawn Routes: %u", wrlen));
        if (cp + wrlen > ep) {
            ND_PRINT((ndo, "\n\t|%s", "truncated"));
            return;
        }
        ND_TCHECK2(*cp, wrlen);
        ND_PRINT((ndo, "\n\t|"));
        print_withdrawn_routes(ndo, cp, wrlen);
        cp += wrlen;
    } else {
        ND_PRINT((ndo, "\n\tWithdrawn Routes: none"));
    }

    if (cp + 2 > ep) {
        ND_PRINT((ndo, "\n\t|%s", "truncated"));
        return;
    }

    attrlen = GET_BE_U_2(cp);
    cp += 2;

    ND_PRINT((ndo, "\n\tPath Attributes: %u", attrlen));
    if (attrlen > 0) {
        if (cp + attrlen > ep) {
            ND_PRINT((ndo, "\n\t|%s", "truncated"));
            return;
        }
        ND_TCHECK2(*cp, attrlen);
        ND_PRINT((ndo, "\n\t|"));
        print_path_attributes(ndo, cp, attrlen);
        cp += attrlen;
    } else {
        ND_PRINT((ndo, "\n\t|No path attributes"));
    }

    if (cp < ep) {
        ND_PRINT((ndo, "\n\tNLRI: %u bytes", (unsigned)(ep - cp)));
        ND_TCHECK2(*cp, (unsigned)(ep - cp));
        print_bgp_nlri(ndo, cp, (unsigned)(ep - cp));
    } else {
        ND_PRINT((ndo, "\n\tNLRI: empty"));
    }

    return;
}

void
bgp_print_update(netdissect_options *ndo, const u_char *dat, int length)
{
    int total_length;
    const u_char *tptr, *end;
    uint16_t withdrawn_routes_length, path_attributes_length;

    tptr = dat;
    end = dat + length;

    if (length < 3) {
        ND_PRINT("%s", " [|truncated BGP update message]");
        return;
    }

    total_length = (tptr[0] << 8) | tptr[1];
    tptr += 2;

    if ((total_length + 2) > length) {
        ND_PRINT("%s", " [truncated BGP update message]");
        return;
    }

    withdrawn_routes_length = (tptr[0] << 8) | tptr[1];
    tptr += 2;

    if (withdrawn_routes_length > (length - 2 - 2)) {
        ND_PRINT("%s", " [truncated withdrawn routes]");
        return;
    }

    /* Print withdrawn routes */
    if (withdrawn_routes_length > 0) {
        ND_PRINT("Withdrawn Routes:\n");
    } else {
        ND_PRINT("No Withdrawn Routes.\n");
    }

    tptr += withdrawn_routes_length;

    path_attributes_length = (tptr[0] << 8) | tptr[1];
    tptr += 2;

    if (path_attributes_length > (length - 2 - withdrawn_routes_length)) {
        ND_PRINT("%s", " [truncated path attributes]");
        return;
    }

    if (path_attributes_length > 0) {
        ND_PRINT("Path Attributes:\n");
        /* Placeholder for path attributes parsing/printing logic */
        while (tptr < (dat + length) && tptr < (tptr + path_attributes_length)) {
            ND_PRINT("Attribute Type: %u\n", *tptr);
            tptr++;
        }
    } else {
        ND_PRINT("No Path Attributes.\n");
    }

    ND_PRINT("End of BGP Update Message.\n");
}

void
process_bgp_update(struct netdissect_options *ndo, const u_char *dat, int length)
{
    int i;
    const u_char *cp;
    int len;

    ND_PRINT((ndo, "BGP update message"));

    if (length < 4) {
        ND_PRINT((ndo, " [truncated BGP update header]"));
        return;
    }

    cp = dat;
    len = length;

    ND_PRINT((ndo, "\n  Withdrawn Routes Length: %d bytes", *cp));
    cp++;
    len--;

    if (len < *cp) {
        ND_PRINT((ndo, " [truncated withdrawn routes]"));
        return;
    }

    for (i = 0; i < *cp; i++) {
        ND_PRINT((ndo, "\n    Withdrawn Route: %s", ipaddr_string(ndo, &cp[i])));
    }
    cp += *cp;
    len -= *cp;

    ND_PRINT((ndo, "\n  Total Path Attribute Length: %d bytes", *cp));
    cp++;
    len--;

    if (len < *cp) {
        ND_PRINT((ndo, " [truncated path attributes]"));
        return;
    }

    if (*cp == 0) {
        ND_PRINT((ndo, "\n  No path attributes"));
    } else {
        ND_PRINT((ndo, "\n  Path Attributes:"));
        for (i = 0; i < *cp; i++) {
            ND_PRINT((ndo, "\n    Attribute[%d]: 0x%x", i, cp[i]));
        }
    }
    cp += *cp;
    len -= *cp;

    if (len > 0) {
        ND_PRINT((ndo, "\n  NLRI:"));
        while (len > 0) {
            if (len < 1) {
                ND_PRINT((ndo, " [truncated NLRI]"));
                return;
            }
            ND_PRINT((ndo, "\n    %s", ipaddr_string(ndo, cp)));
            cp += 4;
            len -= 4;
        }
    } else {
        ND_PRINT((ndo, "\n  Empty NLRI"));
    }
}

void
process_bgp_update(netdissect_options *ndo, const u_char *dat, int length)
{
    const u_char *ptr;
    uint16_t total_length;
    uint16_t withdraw_length;
    int ret;

    if (length < BGP_MSG_HEADER_LEN) {
        ND_PRINT(" [|truncated BGP update message]");
        return;
    }

    ptr = dat;
    total_length = GET_BE16(ptr + 2);
    if (total_length > length) {
        ND_PRINT(" [|truncated BGP update message]");
        return;
    }

    ptr += BGP_MSG_HEADER_LEN;
    length -= BGP_MSG_HEADER_LEN;

    if (length < 4) {
        ND_PRINT(" [|truncated BGP update message]");
        return;
    }

    withdraw_length = GET_BE16(ptr);
    if (withdraw_length > length - 4) {
        ND_PRINT(" [|truncated BGP update message]");
        return;
    }

    ptr += 4;
    length -= 4;

    if (withdraw_length > 0) {
        ND_PRINT("Withdrawn routes (%u bytes):", withdraw_length);
        ret = print_prefixes(ndo, ptr, withdraw_length, BGP_AFI_IPV4);
        if (ret < 0) {
            ND_PRINT(" [|truncated]");
        }
    }

    ptr += withdraw_length;
    length -= withdraw_length;

    if (length < 4) {
        ND_PRINT(" [|truncated BGP update message]");
        return;
    }

    total_length = GET_BE16(ptr);
    if (total_length > length - 4) {
        ND_PRINT(" [|truncated BGP update message]");
        return;
    }

    ptr += 4;
    length -= 4;

    if (total_length > 0) {
        ND_PRINT("Path attributes (%u bytes):", total_length);
        ret = print_bgp_attributes(ndo, ptr, total_length);
        if (ret < 0) {
            ND_PRINT(" [|truncated]");
        }
    }

    ptr += total_length;
    length -= total_length;

    if (length > 0) {
        ND_PRINT("NLRI (%u bytes):", length);
        ret = print_prefixes(ndo, ptr, length, BGP_AFI_IPV4);
        if (ret < 0) {
            ND_PRINT(" [|truncated]");
        }
    } else {
        ND_PRINT("NLRI: empty");
    }
}

void
bgp_print_update(netdissect_options *ndo, const u_char *dat, int length)
{
    const u_char *tp = dat;
    const u_char *tpend = dat + length;
    uint16_t total_length;
    uint16_t withdrawn_routes_length;
    uint16_t path_attributes_length;
    const u_char *wp;

    if (length < 3) {
        ND_PRINT(" [|bgp]");
        return;
    }

    total_length = GET_UINT16(tp + 1);
    if (total_length != length - 3) {
        ND_PRINT("bgp: length mismatch");
    }

    tp += 3;
    withdrawn_routes_length = GET_UINT16(tp);
    tp += 2;
    wp = tp;

    ND_PRINT("bgp: withdrawn routes length %d", withdrawn_routes_length);
    if (withdrawn_routes_length > tpend - tp) {
        ND_PRINT(" [truncated]");
    }

    tp += withdrawn_routes_length;
    path_attributes_length = GET_UINT16(tp);
    tp += 2;

    ND_PRINT("bgp: path attributes length %d", path_attributes_length);
    if (path_attributes_length > tpend - tp) {
        ND_PRINT(" [truncated]");
    }

    if (withdrawn_routes_length == 0 && path_attributes_length == 0) {
        ND_PRINT("bgp: empty NLRI");
    }

    tp += path_attributes_length;
}
